questionvariables.text:
/*finding quartile*/
aa: rand(2)+2;
bb: rand_with_step(4,6,1);/*class limit*/
class_size:bb+1;/*class size*/
/*class intervals*/
x1:aa;/*1st lower class limit*/
x1_1:x1+bb;/*1st upper class limit*/
x2:x1_1+1;/*2nd class lower limit*/
x2_1:x2+bb;/*2nd class upper limit*/
x3:x2_1+1;/*3rd class lower limit*/
x3_1:x3+bb;/*3rd class upper limit*/
x4:x3_1+1;/*4th class lower limit*/
x4_1:x4+bb;/*4th class upper limit*/
x5:x4_1+1;/*5th class lower limit*/
x5_1:x5+bb;/*5th class upper limit*/
/*frequencies*/
f1:rand(2)+2;/* first frequency*/
f2:rand_with_prohib(1,4,[f1]);/* second frequency*/
f3:rand_with_prohib(2,6,[f1,f2]);/* 3rd frequency*/
f4:rand_with_prohib(2,6,[f1,f2,f3]);/* 4th frequency*/
partial_sum:f1+f2+f3+f4;
total_frequencies:rand_with_step(20,60,4);/*n*/
f5:total_frequencies-partial_sum;/* 5th frequency*/
/*Identification of classes*/
class_1:1;
class_2:2;
class_3:3;
class_4:4;
class_5:5;
class_6:6;
/*Pick up correct boundaries*/
bd_class1: x1-0.5;
bd_class2: x1_1+0.5;
bd_class3: x2_1+0.5;
bd_class4: x3_1+0.5;
bd_class5: x4_1+0.5;
bd_class6:x5_1+0.5;
/*cumulative frequencies*/
cf_1:f1;
cf_2:cf_1+f2;
cf_3:cf_2+f3;
cf_4:cf_3+f4;
cf_5:cf_4+f5;
/* q1 variables and conditions*/
q1:total_frequencies/4;
class_q1:if  q1> cf_5 then class_6 elseif q1> cf_4 then class_5 elseif q1> cf_3 then class_4 elseif q1>cf_2 then class_3 elseif q1> cf_1 then class_2 else class_1;
bd_q1: if class_q1=class_6 then bd_class6 elseif class_q1=class_5 then bd_class5 elseif class_q1=class_4 then bd_class4 elseif class_q1=class_3 then bd_class3 elseif class_q1=class_2 then bd_class1 elseif class_q1=class_1 then bd_class1;
choosing_cf: if class_q1=class_6 then cf_5 elseif class_q1=class_5 then cf_4 elseif class_q1=class_4 then cf_3 elseif class_q1=class_3 then cf_2 elseif class_q1=class_2 then cf_1 else cf_1;/*Choose cumulative frequency depending on class*/
choosing_freq: if class_q1=class_6 then f5 elseif class_q1=class_5 then f5 elseif class_q1=class_4 then f4 elseif class_q1=class_3 then f3 elseif class_q1=class_2 then f2 elseif  class_q1=class_1 then f1; /*Choice of frequency */
soln1:((q1-choosing_cf)/choosing_freq);
soln2:soln1*class_size;
ta1:decimalplaces((bd_q1+soln2),2);

/*q2*/
q2:2/4*total_frequencies;
class_q2:if  q2> cf_5 then class_6 elseif q2> cf_4 then class_5 elseif q2> cf_3 then class_4 elseif q2>cf_2 then class_3 elseif q2> cf_1 then class_2 else class_1;
bd_q2: if class_q2=class_6 then bd_class6 elseif class_q2=class_5 then bd_class5 elseif class_q2=class_4 then bd_class4 elseif class_q2=class_3 then bd_class3 elseif class_q2=class_2 then bd_class1 elseif class_q2=class_1 then bd_class1;
choosing_cf_q2: if class_q2=class_6 then cf_5 elseif class_q2=class_5 then cf_4 elseif class_q2=class_4 then cf_3 elseif class_q2=class_3 then cf_2 elseif class_q2=class_2 then cf_1 else cf_1;/*Choose cumulative frequency depending on class*/
choosing_freq_q2: if class_q2=class_6 then f5 elseif class_q2=class_5 then f5 elseif class_q2=class_4 then f4 elseif class_q2=class_3 then f3 elseif class_q2=class_2 then f2 elseif  class_q2=class_1 then f1; /*Choice of frequency */
soln3:((q2-choosing_cf_q2)/choosing_freq_q2);
soln4:soln3*class_size;
ta2:decimalplaces((bd_q2+soln4),2);

/*q3*/
q3:3/4*total_frequencies;
class_q3:if  q3> cf_5 then class_6 elseif q3> cf_4 then class_5 elseif q3> cf_3 then class_4 elseif q3>cf_2 then class_3 elseif q3> cf_1 then class_2 else class_1;
bd_q3: if class_q3=class_6 then bd_class6 elseif class_q3=class_5 then bd_class5 elseif class_q3=class_4 then bd_class4 elseif class_q3=class_3 then bd_class3 elseif class_q3=class_2 then bd_class1 elseif class_q3=class_1 then bd_class1;
choosing_cf_q3: if class_q3=class_6 then cf_5 elseif class_q3=class_5 then cf_4 elseif class_q3=class_4 then cf_3 elseif class_q3=class_3 then cf_2 elseif class_q3=class_2 then cf_1 else cf_1;/*Choose cumulative frequency depending on class*/
choosing_freq_q3: if class_q3=class_6 then f5 elseif class_q3=class_5 then f5 elseif class_q3=class_4 then f4 elseif class_q3=class_3 then f3 elseif class_q3=class_2 then f2 elseif  class_q3=class_1 then f1; /*Choice of frequency */
soln5:((q3-choosing_cf_q3)/choosing_freq_q3);
soln6:soln5*class_size;
ta3:decimalplaces((bd_q3+soln6),2);

/*possible mistakes*/
mistake1:((q3-choosing_freq)/choosing_cf);
inpt1:mistake1*class_size;
mistake_1:decimalplaces((bd_q3+inpt1),2);
/*input mistake 2*/
mistake2:((q2-choosing_freq_q2)/choosing_cf_q2);
inpt2:mistake2*class_size;
mistake_2:decimalplaces((bd_q2+inpt2),2);
/*input mistake 3*/
mistake3:((q2-choosing_freq_q3)/choosing_cf_q3);
inpt3:mistake3*class_size;
mistake_3:decimalplaces((bd_q2+inpt3),2);
/*Power of each class*/
power_Q1: if class_q1=class_1 then "st" elseif class_q1=class_2 then "nd" elseif class_q1=class_3 then "rd" else "th";
power_Q2: if class_q2=class_1 then "st" elseif class_q2=class_2 then "nd" elseif class_q2=class_3 then "rd" else "th";
power_Q3: if class_q2=class_1 then "st" elseif class_q2=class_2 then "nd" elseif class_q2=class_3 then "rd" else "th";

questionnote.text:
class size={@class_size@},
total frequenicies={@total_frequencies@},
q1={@ta1@},
q2={@ta2@},
q3={@ta3@}

feedbackvariables.text:
/*noode 1:checks for the correct answer*/
/*node 2: Interchanging the position of frequency with cumulative frequency*/
mistake_1:decimalplaces((bd_q3+inpt1),2);
/*node 3: Input correct answer in terms of fraction*/
ta1_s: bd_q1+soln2;

/*noode 1:checks for the correct answer*/
/*node 2:Interchanging the position of frequency with cumulative frequency*/
mistake_2:decimalplaces((bd_q2+inpt2),2);
/*node 3: Check alternative correct answer, which is in exact form*/
ta2_s: bd_q2+soln4;

/*noode 1:checks for the correct answer*/
/*node 2:Interchanging the position of frequency with cumulative frequency*/
mistake_3:decimalplaces((bd_q2+inpt3),2);
/*node 3: Check alternative correct answer, which is in exact form*/
ta3_s: bd_q3+soln6;
